"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7527],{80878:e=>{e.exports=JSON.parse('{"functions":[{"name":"startBeam","desc":"Draws a guidance beam from `source` to `target`, replacing any beam\\nalready up. Returns the beam, or nil if either endpoint could not be\\nresolved.\\n\\nBoth endpoints are normalized to `Attachment`s. A `BasePart` source gets a\\nthrowaway attachment parented to it; a `Vector3` or `CFrame` target gets\\none parented to `Workspace.Terrain`. Everything created along the way is\\nowned by the module maid, so [NavigationController.stopBeam] removes it\\nall.\\n\\n```lua\\nNavigationController.startBeam(questGiver.PrimaryPart)\\n\\nNavigationController.ReachedDestination:Once(function()\\n\\tNavigationController.stopBeam()\\nend)\\n```","params":[{"name":"target","desc":"Where the beam points","lua_type":"Attachment | CFrame | Vector3"},{"name":"source","desc":"Beam origin. Defaults to the character\'s PrimaryPart","lua_type":"Attachment | BasePart?"},{"name":"destinationRange","desc":"Arrival radius in studs. Defaults to 4; pass 0 to disable arrival detection entirely","lua_type":"number?"}],"returns":[{"desc":"","lua_type":"Beam?"}],"function_type":"static","source":{"line":113,"path":"src/Client/Features/Core/Controllers/NavigationController.luau"}},{"name":"stopBeam","desc":"Clears the active beam and everything created for it \u2014 the cloned beam,\\nboth throwaway attachments, and the arrival watcher. Clears `isNavigating`\\nand fires `BeamCleared`. Safe to call with no beam up.","params":[],"returns":[],"function_type":"static","source":{"line":196,"path":"src/Client/Features/Core/Controllers/NavigationController.luau"}}],"properties":[],"types":[],"name":"NavigationController","desc":"Draws the \\"go here\\" guidance beam: a single `Assets.Particles.GuidanceBeam`\\nstretched between the local character and a waypoint, which clears itself\\nonce the player arrives.\\n\\nOnly one beam exists at a time. [NavigationController.startBeam] cleans the\\nmodule maid before building anything, so calling it again retargets rather\\nthan stacking beams.\\n\\n### Signals\\n\\n* `ReachedDestination` \u2014 fired once the beam\'s two attachments come within\\n  `destinationRange` studs. Fires immediately, before any connection is\\n  made, if the player is already in range at start.\\n* `BeamCleared` \u2014 fired from the maid\'s own cleanup, so it covers every\\n  teardown path: arrival, an explicit [NavigationController.stopBeam], or\\n  a retarget.\\n\\n`isNavigating` tracks whether a beam is live. Note that arrival flips it\\nfalse but leaves the beam drawn \u2014 the caller decides whether to also call\\n[NavigationController.stopBeam].\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":29,"path":"src/Client/Features/Core/Controllers/NavigationController.luau"}}')}}]);